package com.example.crm.sales;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/deals") public class DealController { final DealRepository repo; DealController(DealRepository r){repo=r;} record Req(@NotBlank String title,BigDecimal amount,UUID customerId){} @GetMapping public List<Deal> all(){return repo.findAll();} @PostMapping public Deal create(@Valid @RequestBody Req r){return repo.save(new Deal(r.title(),r.amount(),r.customerId()));} @PatchMapping("/{id}/stage") public Deal stage(@PathVariable UUID id,@RequestParam Deal.Stage value){var d=repo.findById(id).orElseThrow();d.setStage(value);return repo.save(d);} }
